{
  "name": "@dlacaille/opencode-copilot-instructions",
  "version": "0.4.0",
  "description": "OpenCode plugin that loads GitHub Copilot custom instruction files",
  "type": "module",
  "license": "MIT",
  "exports": {
    ".": "./index.ts"
  },
  "files": [
    "index.ts",
    "src",
    "!src/**/*.test.ts",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "copilot",
    "instructions"
  ],
  "scripts": {
    "test": "vitest run",
    "typecheck": "tsc --noEmit",
    "lint": "biome check",
    "format": "biome check --write"
  },
  "dependencies": {
    "front-matter": "^4.0.2",
    "picomatch": "^4.0.3"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.0.0"
  },
  "devDependencies": {
    "@biomejs/biome": "2.5.14",
    "@opencode/plugin": "^2.0.15",
    "@types/node": "^22.0.0",
    "@types/picomatch": "^4.0.0",
    "typescript": "^5.9.0",
    "vitest": "^4.0.0"
  },
  "publishConfig": {
    "access": "public"
  }
}
